package main

import (
    "testing"
)

func BenchmarkIsValidSubdomain(b *testing.B) {
    validCases := []string{"subdomain", "a.b", "123"}
    invalidCases := []string{"sub@domain", "a b", "a!b"}

    for _, c := range validCases {
        if !isValidSubdomain(c) {
            b.Errorf("Valid subdomain %s was incorrectly marked as invalid", c)
        }
    }

    for _, c := range invalidCases {
        if isValidSubdomain(c) {
            b.Errorf("Invalid subdomain %s was incorrectly marked as valid", c)
        }
    }
}

func main() {
    // Test cases
    println(getURLToVisit("example.com", ""))                     // Should return "https://example.com"
    println(getURLToVisit("example.com", "sub"))                 // Should return "https://sub.example.com"
    println(getURLToVisit("example.com", "a.b"))                 // Should return "https://a.b.example.com"
    println(getURLToVisit("example.com", "invalid@sub"))         // Should return "https://example.com"
}
